// How the regular wave is mixed: weight = min(wMax, w0 + wStep * (round - unlock)).
// cap < 99 limits how many can be alive: min(cap, 1 + (round - unlock) / 6).
typedef struct { uint16_t type, unlock, w0, wStep, wMax, cap; } SpawnDef;
